"""Exact Stage33 source + normal generated bytes, release-shaped but NO refs/deploy."""
from __future__ import annotations
import hashlib,json,os,re,subprocess,sys,zipfile
from pathlib import Path
P=json.loads((Path(__file__).parent/'PINS.json').read_text())
BASE=P['base']; TREE=P['baseTree']; REL=P['source']['path']; MF='web/manifest.json'
SHELL={'HONRO.html','HONRO_WORKSHOP.html','index.html'}
HIST={'publishedRetention','publishedGenerations','previousFiles','previousGenerations'}
D='tools/stage33-r3-release-payload'
BRANCH='refs/heads/qa/stage33-r3-2c4-release-payload'
CARRIER={f'{D}/PINS.json',f'{D}/produce.py','.github/workflows/stage33-r3-2c4-release-payload.yml'}
R2_DELTA={'.github/workflows/stage33-r3-2c4-retained-r2.yml','tools/stage33-r3-product/live_input.py','tools/stage33-r3-product/r2_preflight.py','tools/stage33-r3-product/restore-old-urls.mjs'}
def git(r,*a):return subprocess.check_output(['git','-C',str(r),*a],timeout=140)
def text(r,*a):return git(r,*a).decode().strip()
def sha(b):return hashlib.sha256(b).hexdigest()
def blob(b):return hashlib.sha1(f'blob {len(b)}\0'.encode()+b).hexdigest()
def facts(b):return {'bytes':len(b),'sha256':sha(b)}
def canonical(o):return json.dumps(o,sort_keys=True,separators=(',',':')).encode()
def save(path,o):path.write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n')
def stamped(b):return {**facts(b),'git':blob(b)}
def obj(b):
 def pairs(r):
  o=dict(r);assert len(o)==len(r),'ambiguous JSON'
  return o
 return json.loads(b,object_pairs_hook=pairs)
def address(f):
 p=f['path'];q={k:f[k]for k in ('bytes','sha256')}
 assert re.fullmatch(r'web/(runtime|entries|data|styles|graphics|fonts)/[\w.-]+',p)
 assert isinstance(q['bytes'],int)and q['bytes']>0 and re.fullmatch('[0-9a-f]{64}',q['sha256'])
 return p,q
def inventory(rows):
 o={}
 for f in rows:
  k,v=address(f);assert k not in o or o[k]==v,k;o[k]=v
 return o
def active(m):
 x=inventory(m['files']);assert len(m['files'])==len(x)==810;return x
def registry(m):
 return inventory([*m['files'],*m['previousFiles'],*sum(m['previousGenerations'],[]),*[v for g in m['publishedGenerations'] for v in g['files']]])
def pathread(r,p):
 f=r/p
 assert f.is_file()and not f.is_symlink()and f.resolve()==f,p
 return f.read_bytes()
def normalize_bytes(data):
 for a,b in P['aliases'].items():data=data.replace(b.encode(),a.encode()).replace(Path(b).name.encode(),Path(a).name.encode())
 return data
def normalize_refs(x):
 if isinstance(x,str):
  for a,b in P['aliases'].items():
   if x==b or x.startswith(b+'?'):return a+x[len(b):]
 elif isinstance(x,list):return [normalize_refs(z)for z in x]
 elif isinstance(x,dict):return {k:normalize_refs(v)for k,v in x.items()}
 return x
def bridge(old,normal):
 before=registry(old);now=active(normal);x={**normal,**{k:old[k]for k in HIST}}
 prev=list(old['previousFiles']);have={q['path']for q in prev}
 add=[dict(path=k,**v)for k,v in before.items()if k not in now and k not in have]
 x['previousFiles']=prev+add
 expect={**before,**{k:now[k]for k in P['aliases'].values()}}
 assert len(before)==1329 and len(expect)==1336 and registry(x)==expect
 return x,expect,len(add)
def exact(w):
 r=Path(os.environ['GITHUB_WORKSPACE']).resolve();head=os.environ['GITHUB_SHA'];n=P['normalHead'];q=P['visualParent']
 assert w.is_relative_to(Path(os.environ['RUNNER_TEMP']).resolve()) and w!=Path(os.environ['RUNNER_TEMP']).resolve()
 assert (os.environ['GITHUB_REPOSITORY'],os.environ['GITHUB_REF'],os.environ['GITHUB_EVENT_NAME'])==('sys8994/honro',BRANCH,'push')
 assert text(r,'rev-parse','HEAD')==head and not git(r,'status','--porcelain','-z')
 assert text(r,'rev-parse','--is-shallow-repository')=='false'
 for a,b in ((head,n),(n,q),(q,BASE)):
  assert text(r,'rev-list','--parents','-1',a).split()==[a,b]
 for a,b in ((n,P['normalTree']),(q,P['visualParentTree']),(BASE,TREE)):
  assert text(r,'rev-parse',a+'^{tree}')==b
 for a,b,v in ((n,head,CARRIER),(q,n,R2_DELTA)):
  assert set(text(r,'diff','--name-status','--no-renames',a,b).splitlines())=={'A\t'+x for x in v}
 for x in CARRIER:assert text(r,'ls-tree',head,'--',x).split()[:2]==['100644','blob']
 for p,v in {**P['retainer'],REL:P['source']['old']}.items():
  assert all(text(r,'rev-parse',c+':'+p)==v for c in (BASE,q,n,head))
 old=git(r,'show',BASE+':'+MF);assert facts(old)==P['normalManifestA']
 return r,obj(old)
def api(path):
 return obj(subprocess.check_output(['gh','api','repos/sys8994/honro/'+path],timeout=40))
def authority(w):
 r,old=exact(w)
 assert os.getenv('GH_TOKEN') and not os.getenv('GITHUB_TOKEN')
 assert api('git/ref/heads/master')['object']['sha']==BASE
 q=api(f"actions/runs/{P['normalRun']}"); n=P['normalHead']
 assert (q['id'],q['head_sha'],q['head_branch'],q['path'],q['status'],q['conclusion'],q['event'])==(P['normalRun'],n,P['normalBranch'],P['normalWorkflow'],'completed','success','push')
 assert q['repository']['full_name']==q['head_repository']['full_name']=='sys8994/honro'
 jobs=api(f"actions/runs/{P['normalRun']}/jobs")['jobs'];j=next(x for x in jobs if x['id']==P['normalJob'])
 assert (j['head_sha'],j['status'],j['conclusion'])==(n,'completed','success')
 assert {x['number']:x['conclusion']for x in j['steps'] if 4<=x['number']<=8}==dict.fromkeys(range(4,9),'success')
 ar=P['artifact'];s=api(f"actions/runs/{P['normalRun']}/artifacts")['artifacts']
 assert len(s)==1
 a=s[0];assert (a['id'],a['name'],a['size_in_bytes'],a['digest'],a['expired'])==(ar['id'],ar['name'],ar['bytes'],'sha256:'+ar['sha256'],False)
 assert a['workflow_run']['head_sha']==n and a['workflow_run']['id']==P['normalRun']
 pp=P['pages'];page=api(f"actions/runs/{pp['run']}")
 assert (page['head_sha'],page['head_branch'],page['status'],page['conclusion'])==(BASE,'master','completed','success')
 jd=next(k for k in api(f"actions/runs/{pp['run']}/jobs")['jobs']if k['id']==pp['job'])
 assert jd['name']=='deploy' and jd['conclusion']=='success' and any(k['name']=='Deploy to GitHub Pages' and k['conclusion']=='success' and k['completed_at']==pp['at'] for k in jd['steps'])
 save(w/'authority.json',{'base':BASE,'head':n,'officialArtifact':ar,'priorPages':pp,'verified':True})
def ack(w):
 assert not(os.getenv('GH_TOKEN')or os.getenv('GITHUB_TOKEN'))
 assert obj((w/'authority.json').read_bytes())=={'base':BASE,'head':P['normalHead'],'officialArtifact':P['artifact'],'priorPages':P['pages'],'verified':True}
def pre(w):
 r,old=exact(w);ack(w)
 for k in ('A','B'):git(r,'worktree','add','--detach',str(w/k),BASE)
 assert all(facts(pathread(w/'A',k))==v for k,v in registry(old).items())
def seal(w):
 r,old=exact(w);ack(w);a,b=w/'A',w/'B'
 for x in(a,b):
  assert text(x,'rev-parse','HEAD')==BASE and not text(x,'branch','--show-current')
 assert not git(a,'status','--porcelain','-z')
 stamp=P['source'];src=pathread(b,REL);assert stamped(src)=={'git':stamp['new'],'bytes':stamp['bytes'],'sha256':stamp['sha256']}
 assert git(b,'status','--porcelain','--untracked-files=no','--','shared','tests','tools','game/src','game/engine','workshop/src','package.json','package-lock.json','game/package.json','game/package-lock.json').decode().splitlines()==[' M '+REL]
 fixed=pathread(b,MF);normal=obj(fixed);act=active(normal);before=active(old)
 adds=set(P['aliases'].values());assert set(act)-set(before)==adds and set(before)-set(act)==set(P['aliases'])
 assert len(before.keys()&act.keys())==803 and all(before[k]==act[k]for k in before.keys()&act.keys())
 assert all(facts(pathread(b,k))==v for k,v in act.items())
 assert sha(canonical(act))==P['originalActiveCommonFactsDigest'] and all(act[k]==v for k,v in P['aliasFacts'].items())
 assert {k:normalize_refs(v) for k,v in normal.items()if k not in HIST|{'files'}}=={k:v for k,v in old.items()if k not in HIST|{'files'}}
 assert facts(pathread(a,'HONRO.html'))==P['normalShellA'] and facts(pathread(b,'HONRO.html'))==P['normalShellB']
 for oldpath,newpath in P['aliases'].items():
  if newpath.endswith(('.js','.html')):assert normalize_bytes(pathread(b,newpath))==pathread(a,oldpath),newpath
 for k in SHELL:assert normalize_bytes(pathread(b,k))==pathread(a,k),k
 priorNew=b/'web/data/campaign.d38268efbbeea7a8.json'
 oc=obj(pathread(a,old['project'])); nc=normalize_refs(obj(priorNew.read_bytes()))
 lid=P['wire']['onlyExtraMapElement']['assetId']
 assert nc['libraryOrder'].count(lid)==1
 nc['libraryOrder'].remove(lid);assert nc==oc
 wire=subprocess.check_output(['node',str(r/'tools/stage33-r3-product/prepare.mjs'),'wire',str(w),
  'web/data/chapter-33-assets.4b5df185aa59eb42.json','web/data/chapter-33-assets.07b129345eb95856.json',
  'web/data/chapter-33.a7ce91b7d78fb5f8.json','web/data/chapter-33.80ca32475be181c7.json'],timeout=120)
 assert obj(wire)==P['wire']
 ret=w/'retained';git(r,'worktree','add','--detach',str(ret),BASE)
 assert not git(ret,'status','--porcelain','-z') and text(ret,'rev-parse','HEAD')==BASE
 assert all(facts(pathread(ret,k))==v for k,v in registry(old).items())
 scope={REL,MF,*SHELL,*adds};assert len(scope)==12 and not (adds&set(registry(old)))
 for k in scope-{MF}:
  dest=ret/k;assert dest.parent.resolve()==dest.parent and not dest.is_symlink()
  assert dest.exists()==(k not in adds)
  dest.write_bytes(pathread(b,k))
 bridge0,want,append=bridge(old,normal);save(ret/MF,bridge0)
 pp=P['pages'];evidence=f"https://github.com/sys8994/honro/actions/runs/{pp['run']}"
 with (w/'out'/'retainer.json').open('xb') as f:
  subprocess.run(['node','tools/release/retain-published-web.mjs',BASE,'--published-at',pp['at'],'--evidence',evidence],cwd=ret,stdout=f,check=True,timeout=180)
 final=obj(pathread(ret,MF));assert active(final)==act and registry(final)==want
 assert {k:v for k,v in final.items()if k not in HIST}=={k:v for k,v in normal.items()if k not in HIST}
 assert all(facts(pathread(ret,k))==v for k,v in want.items())
 assert all(pathread(ret,k)==pathread(b,k)for k in scope-{MF})
 now={g['sourceSha']:g for g in final['publishedGenerations']};previous={g['sourceSha']:g for g in old['publishedGenerations']}
 assert BASE in now and BASE not in previous and set(now)<=set(previous)|{BASE}
 assert all(previous[k]==now[k]for k in set(now)-{BASE})
 assert now[BASE]['publishedAt']==pp['at'] and now[BASE]['evidence']==evidence and now[BASE]['files']==old['files']
 assert set(text(ret,'diff','--name-status','--no-renames',BASE).splitlines())=={'M\t'+k for k in scope-adds}
 assert set(text(ret,'ls-files','--others','--exclude-standard').splitlines())==adds
 l={k:{**stamped(pathread(ret,k)),'change':'A'if k in adds else 'M','mode':'100644'}for k in sorted(scope)}
 git(ret,'add','--',*l);t=text(ret,'write-tree')
 assert text(ret,'rev-parse','HEAD')==BASE and set(text(ret,'diff','--cached','--name-status','--no-renames',BASE).splitlines())=={v['change']+'\t'+k for k,v in l.items()}
 for k,v in l.items():assert text(ret,'ls-tree',t,'--',k).split()[:3]==['100644','blob',v['git']]
 z=w/'out'/'STAGE33-12-EXACT-REVIEW-ONLY.zip'
 with zipfile.ZipFile(z,'x',zipfile.ZIP_DEFLATED,compresslevel=8)as f:
  for k in l:
   ii=zipfile.ZipInfo(k,(1980,1,1,0,0,0));ii.external_attr=0o100644<<16;ii.compress_type=zipfile.ZIP_DEFLATED
   f.writestr(ii,pathread(ret,k))
 with zipfile.ZipFile(z)as f:assert f.testzip() is None and set(f.namelist())==set(l) and all(stamped(f.read(k))=={j:l[k][j]for j in ('bytes','sha256','git')}for k in l)
 save(w/'out'/'RETAINED-DELTA-RECEIPT.json',{'status':'SEALED_NORMAL_PRODUCT_BYTES_FOR_REVIEW_ONLY','base':BASE,'tree':t,
  'normalManifest':facts(fixed),'retainedManifest':l[MF],'authority':P['artifact'],'legacyStrictStillFailed':True,
  'active':810,'priorPhysical':1329,'retainedPhysical':1336,'appendCompatibilityAddresses':append,
  'expiredButCompatibleGraphs':len(set(previous)-set(now)),'files':l,'zip':facts(z.read_bytes()),'published':False})
if __name__=='__main__':{'authority':authority,'pre':pre,'seal':seal}[sys.argv[1]](Path(sys.argv[2]).resolve())
